{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "An eligible school is a public school, including a public charter school, that is a senior high school as defined in Section 49-6-401.",
      "rationale": "Fully conveys the eligible-school definition, including public charter schools and the senior-high-school limitation."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The bill defines feminine hygiene products as products or materials designed for feminine hygiene in connection with menstruation or other genital-tract secretions. This includes tampons, panty liners, menstrual cups, sanitary napkins, and similar personal products.",
      "rationale": "Conveys the definition's scope and all listed examples."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "It would require every local education agency (LEA) and public charter school to provide feminine hygiene products at no charge. The products would be placed in all women's and girls' bathrooms, in all locker rooms, and with the school nurse. This applies in each eligible school building where instruction is provided. An eligible school is a public school, including a public charter school, that is a senior high school as defined in Section 49-6-401. Bathrooms and locker rooms set aside specifically for teachers or staff are excluded.",
      "rationale": "Includes the obligated entities, free provision, all required locations, instructional-building scope, and teacher-or-staff facility exception."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The products would be for student use only.",
      "rationale": "Explicitly states the student-only restriction."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The bill also says the department of education may, but is not required to, develop policies and give guidance to help local boards and charter school governing bodies comply.",
      "rationale": "Conveys the department's discretionary authority to develop policies and provide compliance guidance for local education and charter school governance."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The bill would take effect July 1, 2025.",
      "rationale": "States the exact effective date."
    }
  ]
}
